// The first result is the hero, and it lists every other section on the page.
const first = $input.first().json
const settings = $('Settings').first().json
const rest = (first.sections || [])
  .filter(s => s.selector !== first.selector)
  .sort((a, b) => a.order - b.order)
  .slice(0, 15)
return rest.map(s => ({ json: { url: settings.website, selector: s.selector, section: s.label, order: s.order, output: settings.output }, pairedItem: { item: 0 } }))

// Hero plus every section, sorted by where they sit on the page.
const hero = $('Turn the hero into code').first().json
const order = Object.fromEntries((hero.sections || []).map(s => [s.selector, s.order]))
const labelOf = Object.fromEntries((hero.sections || []).map(s => [s.selector, String(s.label || '').split(/\s+/).slice(0, 4).join(' ')]))
const all = [hero, ...$input.all().map(i => i.json)].filter(r => r.code)
  .sort((a, b) => (order[a.selector] ?? (a === hero ? 0 : 999)) - (order[b.selector] ?? (b === hero ? 0 : 999)))
const output = $('Settings').first().json.output
const ext = { tailwind: 'html', html: 'html', jsx: 'jsx', vue: 'vue' }[output] || 'txt'
// File names from the first words of each section.
const slug = s => String(s || 'section').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40)
const binary = {}
all.forEach((r, i) => {
  const name = String(i + 1).padStart(2, '0') + '-' + slug(r === hero ? 'hero' : labelOf[r.selector] || r.selector)
  const text = r.css && ext === 'html' ? '<style>\n' + r.css + '\n</style>\n' + r.code : r.code
  binary['file_' + i] = { data: Buffer.from(text).toString('base64'), mimeType: 'text/plain', fileName: name + '.' + ext, fileExtension: ext }
})
const page = all.filter(r => r.pagePreviewUrl).pop()?.pagePreviewUrl
return [{ json: { sections: all.length, pagePreviewUrl: page }, binary, pairedItem: { item: 0 } }]
